package slashcompletion

import "sort"

func sortedCompletionKeys[T any](m map[string]T) []string {
	if len(m) == 0 {
		return nil
	}
	keys := make([]string, 0, len(m))
	for key := range m {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

func flattenCompletionGroups(groups [][]Completion) []Completion {
	count := 0
	for _, group := range groups {
		count += len(group)
	}
	if count == 0 {
		return nil
	}
	merged := make([]Completion, 0, count)
	for _, group := range groups {
		merged = append(merged, group...)
	}
	return merged
}

type slashCompletionCandidate struct {
	Name         string
	Display      string
	Description  string
	ArgumentHint string
}

type candidateAdmission struct {
	Identity     completionIdentity
	Accepted     bool
	Empty        bool
	Duplicate    bool
	PrefixMissed bool
}

type slashCompletionCandidatePlan struct {
	Completions   []Completion
	EmptyDropped  int
	PrefixMissed  int
	DuplicateKeys []string
}

func (p slashCompletionCandidatePlan) empty() bool {
	return len(p.Completions) == 0
}

func planSlashCompletionCandidates(prefix completionPrefix, candidates []slashCompletionCandidate) slashCompletionCandidatePlan {
	if len(candidates) == 0 {
		return slashCompletionCandidatePlan{}
	}
	seen := make(map[string]struct{}, len(candidates))
	plan := slashCompletionCandidatePlan{Completions: make([]Completion, 0, len(candidates))}
	for _, candidate := range candidates {
		admission := admitCompletionCandidate(candidate.Name, prefix, seen)
		if admission.Empty {
			plan.EmptyDropped++
			continue
		}
		if admission.Duplicate {
			plan.DuplicateKeys = append(plan.DuplicateKeys, admission.Identity.Key)
			continue
		}
		if !admission.Accepted {
			if admission.PrefixMissed {
				plan.PrefixMissed++
			}
			continue
		}
		plan.Completions = append(plan.Completions, Completion{
			Name:         candidate.Name,
			Display:      candidate.Display,
			Description:  candidate.Description,
			ArgumentHint: candidate.ArgumentHint,
			Available:    true,
		})
	}
	return finishSlashCompletionCandidatePlan(plan)
}

func admitCompletionCandidate(rawName string, prefix completionPrefix, seen map[string]struct{}) candidateAdmission {
	identity := newCompletionIdentity(rawName)
	if !identity.valid() {
		return candidateAdmission{Identity: identity, Empty: true}
	}
	if !prefix.matches(identity.Name) {
		return candidateAdmission{Identity: identity, PrefixMissed: true}
	}
	if _, ok := seen[identity.Key]; ok {
		return candidateAdmission{Identity: identity, Duplicate: true}
	}
	seen[identity.Key] = struct{}{}
	return candidateAdmission{Identity: identity, Accepted: true}
}

func finishSlashCompletionCandidatePlan(plan slashCompletionCandidatePlan) slashCompletionCandidatePlan {
	if len(plan.Completions) == 0 {
		plan.Completions = nil
		return plan
	}
	sort.Slice(plan.Completions, func(i, j int) bool {
		return completionKey(plan.Completions[i].Name) < completionKey(plan.Completions[j].Name)
	})
	return plan
}

type uniqueCompletionPlan struct {
	Completions   []Completion
	EmptyDropped  int
	DuplicateKeys []string
}

func (p uniqueCompletionPlan) empty() bool {
	return len(p.Completions) == 0
}

func planUniqueCompletions(candidates []Completion) uniqueCompletionPlan {
	if len(candidates) == 0 {
		return uniqueCompletionPlan{}
	}
	seen := make(map[string]struct{}, len(candidates))
	out := make([]Completion, 0, len(candidates))
	plan := uniqueCompletionPlan{}
	for _, c := range candidates {
		identity := newCompletionIdentity(c.Name)
		if !identity.valid() {
			plan.EmptyDropped++
			continue
		}
		if _, ok := seen[identity.Key]; ok {
			plan.DuplicateKeys = append(plan.DuplicateKeys, identity.Key)
			continue
		}
		seen[identity.Key] = struct{}{}
		out = append(out, c)
	}
	plan.Completions = out
	return finishUniqueCompletionPlan(plan)
}

func finishUniqueCompletionPlan(plan uniqueCompletionPlan) uniqueCompletionPlan {
	if len(plan.Completions) == 0 {
		plan.Completions = nil
		return plan
	}
	sort.Slice(plan.Completions, func(i, j int) bool {
		return completionKey(plan.Completions[i].Name) < completionKey(plan.Completions[j].Name)
	})
	return plan
}

func uniqueSortedCompletions(candidates []Completion) []Completion {
	plan := planUniqueCompletions(candidates)
	if plan.empty() {
		return nil
	}
	return plan.Completions
}

package slashcompletion

import "strings"

const completionWhitespaceChars = " \t"

type completionRequestKind int

const (
	completionRequestCommand completionRequestKind = iota
	completionRequestSubcommand
)

type completionRequest struct {
	kind          completionRequestKind
	commandPrefix completionPrefix
	base          string
	subPrefix     completionPrefix
}

type completionInputParts struct {
	command           string
	subword           string
	hasSubcommandSlot bool
	hasArgs           bool
}

type completionPrefix string

type completionIdentity struct {
	Name string
	Key  string
}

func newCompletionIdentity(raw string) completionIdentity {
	name := completionName(raw)
	return completionIdentity{Name: name, Key: strings.ToLower(name)}
}

func (id completionIdentity) valid() bool {
	return id.Key != ""
}

func newCompletionPrefix(raw string) completionPrefix {
	return completionPrefix(newCompletionIdentity(raw).Key)
}

func newSubcommandPrefix(raw string) completionPrefix {
	return completionPrefix(completionKey(raw))
}

func (p completionPrefix) string() string {
	return string(p)
}

func (p completionPrefix) matches(name string) bool {
	return strings.HasPrefix(completionKey(name), p.string())
}

func (r completionRequest) commandOnly() bool {
	return r.kind == completionRequestCommand
}

func (r completionRequest) subcommandOnly() bool {
	return r.kind == completionRequestSubcommand
}

func parseCompletionRequest(input string) (completionRequest, bool) {
	parts, ok := splitCompletionInput(input)
	if !ok {
		return completionRequest{}, false
	}
	if parts.commandOnly() {
		return completionRequest{kind: completionRequestCommand, commandPrefix: newCompletionPrefix(parts.command)}, true
	}
	if !parts.subcommandCandidate() {
		return completionRequest{}, false
	}
	base := completionKey(parts.command)
	if base == "" {
		return completionRequest{}, false
	}
	return completionRequest{
		kind:      completionRequestSubcommand,
		base:      "/" + base,
		subPrefix: newSubcommandPrefix(parts.subword),
	}, true
}

func splitCompletionInput(input string) (completionInputParts, bool) {
	if !strings.HasPrefix(input, "/") {
		return completionInputParts{}, false
	}
	sep := indexCompletionWhitespace(input)
	if sep < 0 {
		return completionInputParts{command: input}, true
	}
	subText := trimCompletionWhitespaceLeft(input[sep+1:])
	nextSep := indexCompletionWhitespace(subText)
	if nextSep >= 0 {
		return completionInputParts{command: input[:sep], subword: subText[:nextSep], hasSubcommandSlot: true, hasArgs: true}, true
	}
	return completionInputParts{command: input[:sep], subword: subText, hasSubcommandSlot: true}, true
}

func indexCompletionWhitespace(input string) int {
	return strings.IndexFunc(input, isCompletionWhitespace)
}

func trimCompletionWhitespaceLeft(input string) string {
	return strings.TrimLeft(input, completionWhitespaceChars)
}

func containsCompletionWhitespace(input string) bool {
	return strings.ContainsAny(input, completionWhitespaceChars)
}

func isCompletionWhitespace(r rune) bool {
	return strings.ContainsRune(completionWhitespaceChars, r)
}

func (p completionInputParts) commandOnly() bool {
	return !p.hasSubcommandSlot
}

func (p completionInputParts) subcommandCandidate() bool {
	return p.hasSubcommandSlot && !p.hasArgs
}

func completionNameMatches(name string, prefix completionPrefix) bool {
	return prefix.matches(name)
}

func completionName(name string) string {
	return trimCompletionSlashPrefix(name)
}

func trimCompletionSlashPrefix(name string) string {
	trimmed := strings.TrimSpace(name)
	for strings.HasPrefix(trimmed, "/") {
		trimmed = strings.TrimSpace(strings.TrimLeft(trimmed, "/"))
	}
	return trimmed
}

func completionKey(name string) string {
	return newCompletionIdentity(name).Key
}

package slashcompletion

import (
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/platform/cli"
)

type acceptedTextPlan struct {
	Text    string
	Changed bool
	Reason  acceptedTextReason
}

type acceptedTextReason string

const (
	acceptedTextReasonEmptyCompletion  acceptedTextReason = "empty-completion"
	acceptedTextReasonSubcommand       acceptedTextReason = "subcommand"
	acceptedTextReasonExactRejected    acceptedTextReason = "exact-rejected"
	acceptedTextReasonUnsupportedInput acceptedTextReason = "unsupported-input"
	acceptedTextReasonCommand          acceptedTextReason = "command"
)

func AcceptedText(input string, completion Completion, acceptExact bool) (string, bool) {
	plan := planAcceptedText(input, completion, acceptExact)
	return plan.Text, plan.Changed
}

func planAcceptedText(input string, completion Completion, acceptExact bool) acceptedTextPlan {
	accepted := newAcceptedCompletion(completion)
	if accepted.empty() {
		return acceptedTextPlan{Text: input, Reason: acceptedTextReasonEmptyCompletion}
	}
	if inputHasCompletionArguments(input) {
		return acceptedTextPlan{Text: input, Reason: acceptedTextReasonUnsupportedInput}
	}
	if flow, ok := resolveSubcommandFlow(input); ok {
		if !acceptedSubcommandCandidate(flow, accepted) {
			return acceptedTextPlan{Text: input, Reason: acceptedTextReasonUnsupportedInput}
		}
		return planAcceptedSubcommandText(input, flow, accepted, acceptExact)
	}
	if !acceptedCommandCandidate(input, accepted) {
		return acceptedTextPlan{Text: input, Reason: acceptedTextReasonUnsupportedInput}
	}

	next := "/" + accepted.name
	decision := decideAcceptedCommandText(next, newCompletionPrefix(input).string() == accepted.key, accepted.shouldAppendSpace(), acceptExact)
	if decision.exact && !acceptExact {
		return acceptedTextPlan{Text: input, Reason: acceptedTextReasonExactRejected}
	}
	return acceptedTextPlan{Text: decision.text, Changed: decision.text != input, Reason: acceptedTextReasonCommand}
}

type acceptedCommandTextDecision struct {
	text  string
	exact bool
}

func decideAcceptedCommandText(normalized string, exact, appendSpace, acceptExact bool) acceptedCommandTextDecision {
	decision := acceptedCommandTextDecision{
		text:  normalized,
		exact: exact,
	}
	if appendSpace && (acceptExact || !decision.exact) {
		decision.text += " "
	}
	return decision
}

func planAcceptedSubcommandText(input string, flow subcommandFlow, accepted acceptedCompletion, acceptExact bool) acceptedTextPlan {
	next := flow.Base + " " + accepted.name
	decision := decideAcceptedSubcommandText(next, flow.Prefix.string() == accepted.key, acceptExact)
	if decision.exact && !acceptExact {
		return acceptedTextPlan{Text: input, Reason: acceptedTextReasonExactRejected}
	}
	return acceptedTextPlan{Text: decision.text, Changed: decision.text != input, Reason: acceptedTextReasonSubcommand}
}

type acceptedSubcommandTextDecision struct {
	text  string
	exact bool
}

func decideAcceptedSubcommandText(normalized string, exact, acceptExact bool) acceptedSubcommandTextDecision {
	decision := acceptedSubcommandTextDecision{
		text:  normalized,
		exact: exact,
	}
	if acceptExact && decision.exact {
		decision.text += " "
	}
	return decision
}

func inputHasCompletionArguments(input string) bool {
	parts, ok := splitCompletionInput(input)
	return ok && parts.hasArgs
}

func acceptedCommandCandidate(input string, accepted acceptedCompletion) bool {
	req, ok := parseCompletionRequest(input)
	return ok && req.commandOnly() && req.commandPrefix.matches(accepted.name)
}

func acceptedSubcommandCandidate(flow subcommandFlow, accepted acceptedCompletion) bool {
	for _, candidate := range matchingSubcommandCandidates(flow.Subcommands, flow.Prefix) {
		if candidate.key == accepted.key {
			return true
		}
	}
	return false
}

type acceptedCompletion struct {
	name         string
	key          string
	argumentHint string
}

func newAcceptedCompletion(completion Completion) acceptedCompletion {
	name := completionName(completion.Name)
	return acceptedCompletion{
		name:         name,
		key:          completionKey(name),
		argumentHint: strings.TrimSpace(completion.ArgumentHint),
	}
}

func (c acceptedCompletion) empty() bool {
	return c.name == ""
}

func (c acceptedCompletion) shouldAppendSpace() bool {
	return decideAcceptedCompletionSpacing(c).AppendSpace
}

type acceptedCompletionSpacingDecision struct {
	AppendSpace bool
	Reason      acceptedCompletionSpacingReason
}

type acceptedCompletionSpacingReason string

const (
	acceptedCompletionSpacingEmpty             acceptedCompletionSpacingReason = "empty"
	acceptedCompletionSpacingNoTrailingSpace   acceptedCompletionSpacingReason = "no-trailing-space"
	acceptedCompletionSpacingPolicySubcommands acceptedCompletionSpacingReason = "policy-subcommands"
	acceptedCompletionSpacingPolicyArgument    acceptedCompletionSpacingReason = "policy-argument"
	acceptedCompletionSpacingArgumentHint      acceptedCompletionSpacingReason = "argument-hint"
	acceptedCompletionSpacingUnknown           acceptedCompletionSpacingReason = "unknown"
)

func decideAcceptedCompletionSpacing(c acceptedCompletion) acceptedCompletionSpacingDecision {
	if c.empty() {
		return acceptedCompletionSpacingDecision{Reason: acceptedCompletionSpacingEmpty}
	}
	if _, ok := noTrailingSpaceCommands[c.key]; ok {
		return acceptedCompletionSpacingDecision{Reason: acceptedCompletionSpacingNoTrailingSpace}
	}
	if policy, ok := cli.ResolveCommandPolicy(c.key); ok {
		policyKey := completionKey(policy.Name)
		if _, ok := noTrailingSpaceCommands[policyKey]; ok {
			return acceptedCompletionSpacingDecision{Reason: acceptedCompletionSpacingNoTrailingSpace}
		}
		if len(policy.Subcommands) > 0 {
			return acceptedCompletionSpacingDecision{AppendSpace: true, Reason: acceptedCompletionSpacingPolicySubcommands}
		}
		if _, ok := argumentCommandNames[policyKey]; ok {
			return acceptedCompletionSpacingDecision{AppendSpace: true, Reason: acceptedCompletionSpacingPolicyArgument}
		}
		return acceptedCompletionSpacingDecision{Reason: acceptedCompletionSpacingUnknown}
	}
	if c.argumentHint != "" {
		return acceptedCompletionSpacingDecision{AppendSpace: true, Reason: acceptedCompletionSpacingArgumentHint}
	}
	return acceptedCompletionSpacingDecision{Reason: acceptedCompletionSpacingUnknown}
}

var noTrailingSpaceCommands = map[string]struct{}{
	"model":       {},
	"personality": {},
	"provider":    {},
	"skin":        {},
}

var argumentCommandNames = map[string]struct{}{
